-- Modify "shipments" table
ALTER TABLE "shipments" ADD CONSTRAINT "shipments_confirmation_requires_delivered_status" CHECK ((confirmed_received_at IS NULL) OR ((status)::text = 'delivered'::text)), ADD CONSTRAINT "shipments_delivered_at_requires_delivered_status" CHECK ((delivered_at IS NULL) OR ((status)::text = 'delivered'::text)), ADD CONSTRAINT "shipments_delivered_requires_confirmation" CHECK (((status)::text <> 'delivered'::text) OR ((delivered_at IS NOT NULL) AND (confirmed_received_at IS NOT NULL) AND (confirmation_source IS NOT NULL) AND (confirmed_by_actor_id IS NOT NULL)));
